                "m_def": "nomad.datamodel.metainfo.plot.PlotlyFigureQuantity",
                "m_def_id": "5a6e88b4b4d37b09be0de06e6f803c7ead57857e",
                "m_parent_index": 0,
                "m_parent_sub_section": "quantities",
                "name": "figure",
