            "m_def_id": "5af9fa25ccb1e455a969321bf14a8da9dd8cbc89",
            "m_parent_index": 7,
            "m_parent_sub_section": "section_definitions",
            "name": "Forces",
            "description": "Section containing all forces types and contributions.",
